"use client"

import * as React from "react"
import {
  LayoutDashboard,
  Users,
  BarChart3,
  Settings,
  Bell,
  Search,
  Menu,
  X,
  LogOut,
  ChevronRight,
  CreditCard,
  FileText,
  HelpCircle,
} from "lucide-react"
import { cn } from "@aetherstack/utils"
import { Input } from "@aetherstack/ui"

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DashboardNavItem {
  icon?: React.ReactNode
  label: string
  href: string
  badge?: string | number
  active?: boolean
}

export interface DashboardNavGroup {
  label?: string
  items: DashboardNavItem[]
}

export interface DashboardShellProps {
  /** App / product name shown in the sidebar header */
  appName?: string
  /** Navigation groups */
  navGroups?: DashboardNavGroup[]
  /** User display name */
  userName?: string
  /** User email / role shown below name */
  userEmail?: string
  /** User avatar URL */
  userAvatarUrl?: string
  /** Topbar: page title or breadcrumb */
  pageTitle?: React.ReactNode
  /** Topbar: right-side actions */
  headerActions?: React.ReactNode
  /** Page content */
  children: React.ReactNode
  className?: string
}

// ── Default nav ────────────────────────────────────────────────────────────────

const DEFAULT_NAV: DashboardNavGroup[] = [
  {
    items: [
      { icon: <LayoutDashboard className="h-4 w-4" />, label: "Dashboard", href: "/dashboard", active: true },
      { icon: <Users className="h-4 w-4" />, label: "Users", href: "/users", badge: 4 },
      { icon: <BarChart3 className="h-4 w-4" />, label: "Analytics", href: "/analytics" },
      { icon: <CreditCard className="h-4 w-4" />, label: "Billing", href: "/billing" },
      { icon: <FileText className="h-4 w-4" />, label: "Reports", href: "/reports" },
    ],
  },
  {
    label: "Settings",
    items: [
      { icon: <Settings className="h-4 w-4" />, label: "General", href: "/settings" },
      { icon: <HelpCircle className="h-4 w-4" />, label: "Help & Support", href: "/support" },
    ],
  },
]

// ── NavItem ────────────────────────────────────────────────────────────────────

function SidebarNavItem({ item }: { item: DashboardNavItem }) {
  return (
    <a
      href={item.href}
      aria-current={item.active ? "page" : undefined}
      className={cn(
        "group flex items-center gap-2.5 rounded-md px-3 py-2 text-sm transition-colors",
        item.active
          ? "bg-sidebar-accent text-sidebar-accent-foreground font-medium"
          : "text-sidebar-foreground/70 hover:bg-sidebar-accent/50 hover:text-sidebar-foreground",
      )}
    >
      {item.icon && (
        <span className="flex h-4 w-4 shrink-0 items-center justify-center">{item.icon}</span>
      )}
      <span className="flex-1 truncate">{item.label}</span>
      {item.badge !== undefined && (
        <span className="rounded-full bg-primary/15 px-1.5 py-0.5 text-[10px] font-medium text-primary">
          {item.badge}
        </span>
      )}
    </a>
  )
}

// ── DashboardShell ─────────────────────────────────────────────────────────────

export function DashboardShell({
  appName = "Acme",
  navGroups = DEFAULT_NAV,
  userName = "Alex Johnson",
  userEmail = "alex@acme.com",
  pageTitle = "Dashboard",
  headerActions,
  children,
  className,
}: DashboardShellProps) {
  const [sidebarOpen, setSidebarOpen] = React.useState(true)

  return (
    <div className={cn("flex h-screen overflow-hidden bg-background", className)}>
      {/* ── Sidebar ──────────────────────────────────────────────────────── */}
      <aside
        className={cn(
          "flex shrink-0 flex-col border-r border-sidebar-border bg-sidebar-background transition-all duration-200",
          sidebarOpen ? "w-60" : "w-[60px]",
        )}
      >
        {/* Logo / app name */}
        <div className="flex h-14 items-center gap-2.5 border-b border-sidebar-border px-3">
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-primary text-[11px] font-bold text-primary-foreground">
            {appName.charAt(0)}
          </div>
          {sidebarOpen && (
            <span className="truncate text-sm font-semibold text-sidebar-foreground">
              {appName}
            </span>
          )}
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto px-2 py-3 space-y-4">
          {navGroups.map((group, gi) => (
            <div key={gi} className="space-y-0.5">
              {group.label && sidebarOpen && (
                <p className="mb-1 px-3 text-[10px] font-semibold uppercase tracking-wider text-sidebar-foreground/40">
                  {group.label}
                </p>
              )}
              {group.items.map((item) =>
                sidebarOpen ? (
                  <SidebarNavItem key={item.href} item={item} />
                ) : (
                  <a
                    key={item.href}
                    href={item.href}
                    title={item.label}
                    aria-current={item.active ? "page" : undefined}
                    className={cn(
                      "flex h-9 w-9 items-center justify-center rounded-md text-sm transition-colors mx-auto",
                      item.active
                        ? "bg-sidebar-accent text-sidebar-accent-foreground"
                        : "text-sidebar-foreground/60 hover:bg-sidebar-accent/50 hover:text-sidebar-foreground",
                    )}
                  >
                    {item.icon}
                  </a>
                ),
              )}
            </div>
          ))}
        </nav>

        {/* User / bottom */}
        <div className="border-t border-sidebar-border p-2">
          {sidebarOpen ? (
            <div className="flex items-center gap-2.5 rounded-md px-2 py-2 hover:bg-sidebar-accent/50 transition-colors cursor-pointer">
              <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary/15 text-xs font-semibold text-primary">
                {userName.charAt(0)}
              </div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-xs font-medium text-sidebar-foreground">{userName}</p>
                <p className="truncate text-[10px] text-sidebar-foreground/50">{userEmail}</p>
              </div>
              <LogOut className="h-3.5 w-3.5 shrink-0 text-sidebar-foreground/40" />
            </div>
          ) : (
            <div className="flex h-9 w-9 mx-auto items-center justify-center rounded-full bg-primary/15 text-xs font-semibold text-primary cursor-pointer">
              {userName.charAt(0)}
            </div>
          )}
        </div>
      </aside>

      {/* ── Main ─────────────────────────────────────────────────────────── */}
      <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
        {/* Topbar */}
        <header className="flex h-14 shrink-0 items-center gap-3 border-b border-border bg-background px-4">
          <button
            onClick={() => setSidebarOpen((v) => !v)}
            className="flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
            aria-label={sidebarOpen ? "Collapse sidebar" : "Expand sidebar"}
          >
            {sidebarOpen ? <X className="h-4 w-4" /> : <Menu className="h-4 w-4" />}
          </button>

          {typeof pageTitle === "string" ? (
            <div className="flex items-center gap-1.5 text-sm">
              <span className="text-muted-foreground">Home</span>
              <ChevronRight className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="font-medium text-foreground">{pageTitle}</span>
            </div>
          ) : (
            pageTitle
          )}

          <div className="ml-auto flex items-center gap-2">
            <div className="relative hidden sm:block">
              <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search…"
                className="h-8 w-48 pl-8 text-xs"
              />
            </div>
            <button
              className="relative flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              aria-label="Notifications"
            >
              <Bell className="h-4 w-4" />
              <span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-primary" />
            </button>
            {headerActions}
          </div>
        </header>

        {/* Content */}
        <main className="flex-1 overflow-y-auto p-6">{children}</main>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { cn } from "@aetherstack/utils"
import { Button, Input, Checkbox, Label } from "@aetherstack/ui"
import {
  FormField,
  FormLabel,
  FormControl,
  FormMessage,
} from "@aetherstack/patterns"

export interface LoginBlockProps {
  /** App / product name */
  appName?: string
  /** Tagline shown below the app name */
  tagline?: string
  /** Called when the form is submitted with email and password */
  onSubmit?: (values: { email: string; password: string; remember: boolean }) => void
  /** URL for the sign-up page */
  signUpHref?: string
  /** URL for the forgot-password flow */
  forgotPasswordHref?: string
  /** If provided, shows a split-panel layout with this content on the left */
  panel?: React.ReactNode
  className?: string
}

export function LoginBlock({
  appName = "Aether UI",
  tagline = "Welcome back — sign in to continue.",
  onSubmit,
  signUpHref = "/signup",
  forgotPasswordHref = "/forgot-password",
  panel,
  className,
}: LoginBlockProps) {
  const [email, setEmail] = React.useState("")
  const [password, setPassword] = React.useState("")
  const [remember, setRemember] = React.useState(false)
  const [emailError, setEmailError] = React.useState<string | undefined>()
  const [passwordError, setPasswordError] = React.useState<string | undefined>()

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    let valid = true
    if (!email) { setEmailError("Email is required"); valid = false }
    else if (!/\S+@\S+\.\S+/.test(email)) { setEmailError("Enter a valid email address"); valid = false }
    else setEmailError(undefined)

    if (!password) { setPasswordError("Password is required"); valid = false }
    else if (password.length < 8) { setPasswordError("Password must be at least 8 characters"); valid = false }
    else setPasswordError(undefined)

    if (valid) onSubmit?.({ email, password, remember })
  }

  const formCard = (
    <div className="w-full max-w-sm">
      {/* Logo / app name */}
      <div className="mb-8 flex flex-col items-center text-center">
        <div className="mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-lg font-bold text-primary-foreground">
          {appName.charAt(0)}
        </div>
        <h1 className="text-2xl font-semibold tracking-tight text-foreground">Sign in</h1>
        <p className="mt-1 text-sm text-muted-foreground">{tagline}</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4" noValidate>
        <FormField name="email" {...(emailError ? { error: emailError } : {})}>
          <FormLabel>Email address</FormLabel>
          <FormControl>
            <Input
              type="email"
              placeholder="you@example.com"
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </FormControl>
          <FormMessage />
        </FormField>

        <FormField name="password" {...(passwordError ? { error: passwordError } : {})}>
          <div className="flex items-center justify-between">
            <FormLabel>Password</FormLabel>
            <a
              href={forgotPasswordHref}
              className="text-xs text-primary underline-offset-4 hover:underline"
            >
              Forgot password?
            </a>
          </div>
          <FormControl>
            <Input
              type="password"
              placeholder="••••••••"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </FormControl>
          <FormMessage />
        </FormField>

        <div className="flex items-center gap-2">
          <Checkbox
            id="remember"
            checked={remember}
            onCheckedChange={(v) => setRemember(Boolean(v))}
          />
          <Label htmlFor="remember" className="text-sm font-normal text-muted-foreground cursor-pointer">
            Remember me for 30 days
          </Label>
        </div>

        <Button type="submit" className="w-full">
          Sign in
        </Button>
      </form>

      <p className="mt-6 text-center text-sm text-muted-foreground">
        Don&apos;t have an account?{" "}
        <a href={signUpHref} className="text-primary underline-offset-4 hover:underline font-medium">
          Sign up
        </a>
      </p>
    </div>
  )

  if (panel) {
    return (
      <div className={cn("flex min-h-screen bg-background", className)}>
        {/* Left panel */}
        <div className="hidden w-1/2 items-center justify-center bg-muted/30 p-12 lg:flex">
          {panel}
        </div>
        {/* Right: form */}
        <div className="flex flex-1 items-center justify-center p-8">
          {formCard}
        </div>
      </div>
    )
  }

  return (
    <div className={cn("flex min-h-screen items-center justify-center bg-muted/20 p-6", className)}>
      <div className="w-full max-w-sm rounded-xl border border-border bg-card p-8 shadow-sm">
        {formCard}
      </div>
    </div>
  )
}

import * as React from "react"
import { cn } from "@aetherstack/utils"

export interface EmptyStateProps {
  /** Icon element — recommended size: h-10 w-10 */
  icon?: React.ReactNode
  title: string
  description?: string
  /** Primary CTA — typically a Button */
  action?: React.ReactNode
  /** Secondary CTA */
  secondaryAction?: React.ReactNode
  className?: string
}

export function EmptyState({
  icon,
  title,
  description,
  action,
  secondaryAction,
  className,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center rounded-lg border border-dashed border-border bg-muted/20 px-6 py-16 text-center",
        className,
      )}
    >
      {icon && (
        <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-muted text-muted-foreground">
          {icon}
        </div>
      )}
      <h3 className="mb-1 text-base font-semibold text-foreground">{title}</h3>
      {description && (
        <p className="mb-5 max-w-sm text-sm text-muted-foreground">{description}</p>
      )}
      {(action || secondaryAction) && (
        <div className="flex flex-wrap items-center justify-center gap-2">
          {action}
          {secondaryAction}
        </div>
      )}
    </div>
  )
}

import * as React from "react"
import { cn } from "@aetherstack/utils"

export interface ErrorStateProps {
  title?: string
  description?: string
  /** Primary CTA — typically a retry Button */
  action?: React.ReactNode
  className?: string
}

export function ErrorState({
  title = "Something went wrong",
  description = "An unexpected error occurred. Please try again.",
  action,
  className,
}: ErrorStateProps) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center rounded-lg border border-destructive/20 bg-destructive/5 px-6 py-12 text-center",
        className,
      )}
      role="alert"
    >
      {/* Error icon */}
      <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10 text-destructive">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="22"
          height="22"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="10" />
          <line x1="12" x2="12" y1="8" y2="12" />
          <line x1="12" x2="12.01" y1="16" y2="16" />
        </svg>
      </div>
      <h3 className="mb-1 text-base font-semibold text-foreground">{title}</h3>
      {description && (
        <p className="mb-5 max-w-sm text-sm text-muted-foreground">{description}</p>
      )}
      {action}
    </div>
  )
}

"use client"

import * as React from "react"
import { Label } from "@aetherstack/ui"
import { cn } from "@aetherstack/utils"

// ── Context ──────────────────────────────────────────────────────────────────

interface FormFieldContextValue {
  id: string
  name: string | undefined
  error: string | undefined
  required: boolean | undefined
}

const FormFieldContext = React.createContext<FormFieldContextValue | null>(null)

export function useFormField() {
  const ctx = React.useContext(FormFieldContext)
  if (!ctx) throw new Error("useFormField must be used within a FormField")
  return {
    id: ctx.id,
    name: ctx.name,
    labelId: `${ctx.id}-label`,
    descriptionId: `${ctx.id}-description`,
    messageId: `${ctx.id}-message`,
    error: ctx.error,
    required: ctx.required,
  }
}

// ── FormField ─────────────────────────────────────────────────────────────────

export interface FormFieldProps {
  /** Explicit id. Auto-generated from name if omitted. */
  id?: string
  name?: string
  error?: string
  required?: boolean
  className?: string
  children: React.ReactNode
}

export function FormField({
  id: explicitId,
  name,
  error,
  required,
  className,
  children,
}: FormFieldProps) {
  const generatedId = React.useId()
  const id = explicitId ?? (name ? `field-${name}` : generatedId)

  return (
    <FormFieldContext.Provider value={{ id, name, error, required }}>
      <div className={cn("space-y-1.5", className)}>{children}</div>
    </FormFieldContext.Provider>
  )
}

// ── FormLabel ─────────────────────────────────────────────────────────────────

export interface FormLabelProps extends React.ComponentPropsWithoutRef<typeof Label> {}

export const FormLabel = React.forwardRef<
  React.ElementRef<typeof Label>,
  FormLabelProps
>(({ className, children, ...props }, ref) => {
  const { id, error, required } = useFormField()
  return (
    <Label
      ref={ref}
      htmlFor={id}
      className={cn(error && "text-destructive", className)}
      {...props}
    >
      {children}
      {required && (
        <span className="ml-0.5 text-destructive" aria-hidden="true">
          *
        </span>
      )}
    </Label>
  )
})
FormLabel.displayName = "FormLabel"

// ── FormControl ───────────────────────────────────────────────────────────────

export interface FormControlProps {
  children: React.ReactElement
}

export function FormControl({ children }: FormControlProps) {
  const { id, error, descriptionId, messageId } = useFormField()
  return React.cloneElement(children, {
    id,
    "aria-describedby": [descriptionId, error ? messageId : undefined]
      .filter(Boolean)
      .join(" ") || undefined,
    "aria-invalid": error ? true : undefined,
  } as React.HTMLAttributes<HTMLElement>)
}

// ── FormDescription ───────────────────────────────────────────────────────────

export interface FormDescriptionProps
  extends React.HTMLAttributes<HTMLParagraphElement> {}

export const FormDescription = React.forwardRef<
  HTMLParagraphElement,
  FormDescriptionProps
>(({ className, ...props }, ref) => {
  const { descriptionId } = useFormField()
  return (
    <p
      ref={ref}
      id={descriptionId}
      className={cn("text-xs text-muted-foreground", className)}
      {...props}
    />
  )
})
FormDescription.displayName = "FormDescription"

// ── FormMessage ───────────────────────────────────────────────────────────────

export interface FormMessageProps
  extends React.HTMLAttributes<HTMLParagraphElement> {}

export const FormMessage = React.forwardRef<
  HTMLParagraphElement,
  FormMessageProps
>(({ className, children, ...props }, ref) => {
  const { error, messageId } = useFormField()
  const body = error ?? children
  if (!body) return null
  return (
    <p
      ref={ref}
      id={messageId}
      role="alert"
      className={cn("text-xs font-medium text-destructive", className)}
      {...props}
    >
      {body}
    </p>
  )
})
FormMessage.displayName = "FormMessage"

import { Skeleton } from "@aetherstack/ui"
import { cn } from "@aetherstack/utils"

// ── Spinner ───────────────────────────────────────────────────────────────────

function Spinner({ className }: { className?: string }) {
  return (
    <svg
      className={cn("animate-spin", className)}
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
      aria-hidden="true"
    >
      <circle
        className="opacity-25"
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="4"
      />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
      />
    </svg>
  )
}

// ── LoadingState ──────────────────────────────────────────────────────────────

export interface LoadingStateProps {
  /** "spinner" shows a centred spinner; "skeleton" shows skeleton rows */
  variant?: "spinner" | "skeleton"
  /** Number of skeleton rows (only used when variant="skeleton") */
  rows?: number
  text?: string
  className?: string
}

export function LoadingState({
  variant = "spinner",
  rows = 4,
  text = "Loading…",
  className,
}: LoadingStateProps) {
  if (variant === "skeleton") {
    return (
      <div className={cn("space-y-3 p-4", className)} aria-busy="true" aria-label={text}>
        {Array.from({ length: rows }).map((_, i) => (
          <div key={i} className="flex items-center gap-3">
            {i === 0 && <Skeleton className="h-9 w-9 shrink-0 rounded-full" />}
            <div className="flex-1 space-y-2">
              <Skeleton className={cn("h-4", i === 0 ? "w-3/4" : i % 2 === 0 ? "w-5/6" : "w-4/5")} />
              {i === 0 && <Skeleton className="h-3 w-1/2" />}
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-3 py-16 text-center",
        className,
      )}
      aria-busy="true"
      aria-label={text}
    >
      <Spinner className="h-8 w-8 text-primary" />
      {text && <p className="text-sm text-muted-foreground">{text}</p>}
    </div>
  )
}

import * as React from "react"
import { Card, CardContent } from "@aetherstack/ui"
import { cn } from "@aetherstack/utils"

export type MetricTrend = "up" | "down" | "neutral"

export interface MetricCardProps {
  label: string
  value: string | number
  /** e.g. "+12.5%" */
  change?: string
  trend?: MetricTrend
  /** Icon to display in the top-right */
  icon?: React.ReactNode
  /** Optional sublabel below the value */
  sublabel?: string
  className?: string
}

function TrendArrow({ trend }: { trend: MetricTrend }) {
  if (trend === "neutral") return null
  return (
    <svg
      className={cn(
        "h-3 w-3",
        trend === "up" ? "rotate-0 text-emerald-500" : "rotate-180 text-destructive",
      )}
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="3"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M7 17 17 7M7 7h10v10" />
    </svg>
  )
}

export function MetricCard({
  label,
  value,
  change,
  trend = "neutral",
  icon,
  sublabel,
  className,
}: MetricCardProps) {
  return (
    <Card className={cn("overflow-hidden", className)}>
      <CardContent className="p-5">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0 flex-1">
            <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
              {label}
            </p>
            <p className="mt-1.5 text-2xl font-semibold tracking-tight text-foreground">
              {value}
            </p>
            {sublabel && (
              <p className="mt-0.5 text-xs text-muted-foreground">{sublabel}</p>
            )}
            {change && (
              <div
                className={cn(
                  "mt-2 inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium",
